package net.civeira.phylax.feature.access.oauthclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class ClientCredentialsTokenTtlSecondsVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property client credentials token ttl seconds of oauth client ")
  void test_client_credentials_token_ttl_seconds_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class,
        () -> ClientCredentialsTokenTtlSecondsVO.tryFrom(null));
    Assertions.assertEquals(1,
        ClientCredentialsTokenTtlSecondsVO.from(1).getClientCredentialsTokenTtlSeconds());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> ClientCredentialsTokenTtlSecondsVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", ClientCredentialsTokenTtlSecondsVO.from(1).toString());
  }
}
